package com.foodtrip.foodsearch.dto;

public class ScoreDTO {
	
	// 점수를 담을 DTO
	private int l;
	private int s;
	
	private int f;
	private int n;
	
	private int a;
	private int t;
	
	private int p;
	private int i;
	
	public ScoreDTO() {
	// TODO Auto-generated constructor stub
	}

	public ScoreDTO(int l, int s, int f, int n, int a, int t, int p, int i) {
		super();
		this.l = l;
		this.s = s;
		this.f = f;
		this.n = n;
		this.a = a;
		this.t = t;
		this.p = p;
		this.i = i;
	}

	public int getL() {
		return l;
	}

	public void setL(int l) {
		this.l = l;
	}

	public int getS() {
		return s;
	}

	public void setS(int s) {
		this.s = s;
	}

	public int getF() {
		return f;
	}

	public void setF(int f) {
		this.f = f;
	}

	public int getN() {
		return n;
	}

	public void setN(int n) {
		this.n = n;
	}

	public int getA() {
		return a;
	}

	public void setA(int a) {
		this.a = a;
	}

	public int getT() {
		return t;
	}

	public void setT(int t) {
		this.t = t;
	}

	public int getP() {
		return p;
	}

	public void setP(int p) {
		this.p = p;
	}

	public int getI() {
		return i;
	}

	public void setI(int i) {
		this.i = i;
	}	
	
	
	
	
	
	
	
	
}
